/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    //METWHSPalletVolume  whsCaseVolume; // TODO coming from WH containerTypeTable from cardboard
    METQty ret;

    // Keg “PAL” TSIGs are created under the same conditions as described in the same section in the CB624 FSD
    // and with the same logic. Kegs will not have CCR data.
    // DoesCustUseTotes = Y same calc as non CCR
    // calc is the same except when DoesCustUseTotes = N
    ret = super(_quantity);

    if (!isToteCustomer)
    {
        // TODO Add (WhsCaseVolume * Count(CCR_RepackContainersByCommodity) for this CCR_LineCommodity)
        ret += 0;
    }

    return ret;
}

